var UpdateElementStyleSchema = zod.z.object({
  filePath: zod.z.string().describe("Path to the PPTX file"),
  slideIndex: zod.z.number().int().min(0),
  elementId: zod.z.string(),
  fillColor: zod.z.string().optional(),
  /**
   * A theme colour for the fill (e.g. `{ scheme: 'accent1', lumMod: 0.8 }`
   * for "Accent 1, Lighter 80%"). When set, the shape saves as
   * `<a:schemeClr>` and keeps following the theme after a later theme
   * change, instead of freezing today's resolved hex. Setting `fillColor`
   * without this clears any previously-set fill theme colour.
   */
  fillThemeColor: ThemeColorRefSchema2.optional(),
  fillMode: zod.z.string().optional(),
  fillGradientStops: zod.z.array(
    zod.z.object({
      color: zod.z.string(),
      position: zod.z.number(),
      opacity: zod.z.number().optional()
    })
  ).optional(),
  fillGradientAngle: zod.z.number().optional(),
  fillGradientType: zod.z.string().optional(),
  fillOpacity: zod.z.number().optional(),
  strokeColor: zod.z.string().optional(),
  /** A theme colour for the outline; see `fillThemeColor` above. */
  strokeThemeColor: ThemeColorRefSchema2.optional(),
  strokeWidth: zod.z.number().optional(),
  strokeDash: zod.z.string().optional(),
  strokeOpacity: zod.z.number().optional(),
  shadowColor: zod.z.string().optional(),
  shadowBlur: zod.z.number().optional(),
  shadowOffsetX: zod.z.number().optional(),
  shadowOffsetY: zod.z.number().optional(),
  shadowOpacity: zod.z.number().optional(),
  glowColor: zod.z.string().optional(),
  glowRadius: zod.z.number().optional(),
  glowOpacity: zod.z.number().optional(),
  softEdgeRadius: zod.z.number().optional(),
  cropLeft: zod.z.number().optional(),
  cropTop: zod.z.number().optional(),
  cropRight: zod.z.number().optional(),
  cropBottom: zod.z.number().optional(),
  brightness: zod.z.number().optional(),
  contrast: zod.z.number().optional(),
  grayscale: zod.z.boolean().optional(),
  altText: zod.z.string().optional().describe(
    "Accessibility description (p:cNvPr/@descr) for image, picture, table, chart, smartArt, ole, media, text, shape and connector elements"
  ),
  title: zod.z.string().optional().describe(
    "Accessibility title (p:cNvPr/@title) for table, chart, smartArt, ole, media, text, shape and connector elements (not pictures)"
  )
});
